/* @lc app=leetcode id=3980 lang=kotlin */ class Solution{fun minOperations(s1: String, s2: String): Int = s1.indices.joinToString("") { if (s1[it] == '1' && s2[it] == '0') "A" else if (s1[it] == '0' && s2[it] == '1') "B" else "C" }.let { t -> if (s1.length == 1 && 'A' in t) -1 else t.count { it == 'B' } + t.split(Regex("[^A]+")).sumOf { it.length / 2 + 2 * (it.length % 2) } } }